head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST75100";
scwin.AKCDiv = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.AKCDiv = $c.util.getComponent('AKCDiv');
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst75100.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    await scwin.fnOrder('0', 'A');
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        akc_init();
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75100.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
